#ifndef HUD_DATA_H
#define HUD_DATA_H
#include <stdint.h>
/* generated by tools/gen_hud.py - do not edit (re-run after gen_bg.py / gen_assets.py --emit) */
#define HUD_BANK 1u            /* PRG bank of hud_data.c (build.ps1 -Wf-bo1): SWITCH_ROM(HUD_BANK) before reading */
#define HUD_T0 0xAFu          /* first BG tile id (bg + dyn tiles must stay below it) */
#define HUD_NTILES 64u
#define HT_FONT_L HUD_T0                   /* 25 glyphs, bright on black (band text) */
#define HT_FONT_S (HUD_T0 + 25u)           /* 37 glyphs, dark on sky (HUD strip), canonical order */
#define HT_HAT    (HUD_T0 + 62u)
#define HT_BLACK  (HUD_T0 + 63u)           /* solid black: margin / band background */
#define HUD_MARGIN_PAL 2u                 /* BG palette whose colour 1 is black: margins, band */
#define HUD_SKY_PAL 1u                    /* BG palette of the sky strip (sky = colour 1) */
#define HUD_SPR_T0 0xC0u       /* first sprite tile id: minimap markers (NES OBJ table is separate from BG,
                                * so the widened 13 px actor set can use 0..0xBF; hand edits split shared
                                * tiles, so keep headroom: 172 tiles used after the first edit pass) */
#define HUD_NSPR 3u
#define HUD_SPR_PROP0 3u      /* OAM palette of each marker */
#define HUD_SPR_PROP1 2u
#define HUD_SPR_PROP2 2u
extern const uint8_t hud_tiles[HUD_NTILES * 16u];
extern const uint8_t hud_spr[HUD_NSPR * 16u];
extern const uint8_t hud_bmap[37u];   /* canonical char index -> band glyph offset (unused = space) */
#endif
